set-variable.value:
@{
    var jwt = (Jwt)context.Variables["contoso.validatedCallerJwt"];
    string[] scopes;
    if (!jwt.Claims.TryGetValue("scp", out scopes)) return false;
    return scopes.SelectMany(value => value.Split(' ')).Contains("{{contoso-delegated-scope}}");
  }

@{
    var jwt = (Jwt)context.Variables["contoso.validatedCallerJwt"];
    string[] values;
    var clientId = "";
    if (jwt.Claims.TryGetValue("azp", out values) && values.Length == 1) clientId = values[0];
    else if (jwt.Claims.TryGetValue("appid", out values) && values.Length == 1) clientId = values[0];
    string[] roles;
    string[] identityTypes;
    return !(bool)context.Variables["contoso.callerDelegated"]
      && !jwt.Claims.ContainsKey("scp")
      && jwt.Claims.TryGetValue("idtyp", out identityTypes)
      && identityTypes.Length == 1 && identityTypes[0] == "app"
      && jwt.Claims.TryGetValue("roles", out roles)
      && roles.Contains("Portal.Invoke")
      && "{{contoso-portal-client-ids}}".Split(',').Contains(clientId);
  }
